        "dev.refresh": ("\u{5237}\u{65b0}", "Refresh"),
        "dev.team": ("\u{7b7e}\u{540d}\u{56e2}\u{961f}", "Signing team"),
        "dev.noTeam": ("Xcode 里没有 Apple ID，也没有开发证书。打开 Xcode → Settings → Apple Accounts（Xcode 菜单没有中文），登录 Apple ID 后选 Personal Team → Download Manual Profiles。证书不会立刻出现——等 30 秒左右再按「重新检测」。如果等了还没有，在 Manage Certificates 里点 + 手动创建一个 Apple Development 证书。",
                       "No Apple ID in Xcode and no development certificate. Open Xcode → Settings → Apple Accounts (Xcode menus are English-only), sign in with your Apple ID, select Personal Team → Download Manual Profiles. The certificate does not appear immediately — wait ~30 seconds and press Check again. If it still does not appear, click + in Manage Certificates to create an Apple Development certificate manually."),
        "dev.teamNoCert": ("这个团队还没有开发证书：第一次安装时 Xcode 会自动创建（Mac 需要联网）。",
                           "This team has no development certificate yet: Xcode creates it at the first install (the Mac needs to be online)."),
        "dev.personalTeam": ("个人团队", "Personal team"),
        "dev.note": ("Xcode 会为这台设备签名共用应用并安装，然后把游戏数据（romfs.img）复制到应用的“文稿”中。第一次复制大型游戏需要几分钟。第一次需要在设备上开启开发者模式，并信任开发者（设置 → 通用 → VPN 与设备管理）。", "Xcode signs the shared app for this device and installs it there, then copies the game data (romfs.img) into the app’s Documents. The first copy of a large game takes a few minutes. The first time, turn on Developer Mode on the device and trust the developer (Settings → General → VPN & Device Management)."),
