        "dep.guide.iossdk": ("三种获取方式：① 点「安装」由本程序下载（无需 Apple ID，约 100 MB）；② 在 <a href=\"https://developer.apple.com/download/all/\">Apple 开发者下载页</a>（需 Apple ID）搜索 “iPhoneOS” 下载并解压，然后点「选择文件夹…」指向里面的 iPhoneOS*.sdk；③ 已有 Xcode 的 Mac：拷贝 Xcode.app 内 Platforms/iPhoneOS.platform/Developer/SDKs/ 下的同名文件夹到这台电脑。Apple 的 SDK 无法由本程序直接分发。",
                             "Three ways to get it: ① press Install and this app downloads one (no Apple ID, about 100 MB); ② search “iPhoneOS” on the <a href=\"https://developer.apple.com/download/all/\">Apple developer downloads</a> (Apple ID required), unpack, then press Choose folder… and point at the iPhoneOS*.sdk inside; ③ copy the same-named folder from Xcode.app's Platforms/iPhoneOS.platform/Developer/SDKs/ on a Mac that has Xcode. Apple's SDK cannot be shipped by this app."),
        "dep.guide.metal": ("Metal 着色器编译器由 Apple 单独发布：在 <a href=\"https://developer.apple.com/download/all/\">Apple 开发者下载页</a>（需 Apple ID）下载 “Metal Developer Tools for Windows”，解压后点「选择文件夹…」指向解压出的目录（含 metal.exe 或 ios/）。已装的话本程序会在常见位置自动找到。",
                            "The Metal shader compiler ships separately from Apple: download \"Metal Developer Tools for Windows\" from the <a href=\"https://developer.apple.com/download/all/\">Apple developer downloads</a> (Apple ID required), unpack, then press Choose folder… and point at the unpacked folder (holding metal.exe or ios/). An installed copy is found by itself in the usual places."),
