                            "The build script ran with an Intel Python under Rosetta, so the tools it starts would run as Intel code too."),
        "fail.rosetta.next": ("NS Port Builder 有自带的 Python 时会优先使用它。如果这次用的是别的，请删除 ~/Library/Application Support/NS Port Builder/venv 里的 Intel 虚拟环境，再点「重新检测」。",
                            "NS Port Builder uses its bundled Python when it has one. If this build used another, remove the Intel venv in ~/Library/Application Support/NS Port Builder/venv and press Check again."),
