        "fail.zbic.what": ("这个游戏的模块用了 Nintendo 的 zstd 变体压缩（系统 22.0.0 起），读取它需要 Python 包 zbic，而它没有安装。",
                          "This game's modules use Nintendo's zstd variant (system 22.0.0 and later), and reading them needs the Python package zbic, which is not installed."),
        "fail.zbic.next": ("点下面的按钮安装 zbic，然后再构建。也可以在终端里运行 python3 -m pip install zbic，用的是构建所用的那个 Python。",
