                                "The Command Line Tools are selected instead of Xcode, and they have no iOS SDK."),
        "fail.cltSelected.next": ("用下面的按钮选择 Xcode（会要管理员密码），或者在终端运行 sudo xcode-select -s /Applications/Xcode.app，然后再构建。",
                                "Select Xcode with the button below (it asks for an administrator password), or run sudo xcode-select -s /Applications/Xcode.app in Terminal, then build again."),
        "fail.cltSelected.button": ("选择 Xcode",
                                  "Select Xcode"),
        "fail.otherMetal.what": ("这台 Mac 的 Metal 编译器不是着色器测试时用的那一个。",
                               "This Mac's Metal compiler is not the one the shaders were tested with."),
        "fail.otherMetal.next": ("这个游戏使用 NVN，需要 Xcode 27.1（macOS 26.6 或更新）。请安装它和它的 Metal 工具链，然后再构建。",
                               "This game uses NVN and needs Xcode 27.1 (macOS 26.6 or later). Install it and its Metal toolchain, then build again."),
        "fail.otherMetal.risk": ("会用没有测试过的 Metal 编译器构建。画面可能出错，结果也没有人测试过，不受支持。这个选择只对这一次构建有效，不会保存。",
                               "This builds with a Metal compiler nobody tested the shaders with. The pictures can come out wrong, the result is untested and it is not supported. The choice applies to this one build and is not saved."),
        "fail.shaderRegression.what": ("有些以前能翻译的着色器，在这个版本里翻译失败了。",
                                     "Some shaders that translated before fail to translate with this version."),
        "fail.shaderRegression.next": ("请带上构建日志里的列表去报告这个问题。「仍然构建」会把这些着色器留空，所以画面可能缺少一部分。",
                                     "Please report it with the list in the build log. Building anyway leaves those shaders out, so parts of the picture may be missing."),
        "fail.shaderRegression.risk": ("会在没有这些着色器的情况下打包。画面可能缺少一部分，结果也没有人测试过。这个选择只对这一次构建有效，不会保存。",
                                     "This packs the app without those shaders. Parts of the picture may be missing and the result is untested. The choice applies to this one build and is not saved."),
        "fail.damagedNSP.what": ("游戏文件已损坏，没有通过 NCA 的哈希校验，常见原因是复制不完整或下载中断。",
                               "The game file is damaged. It fails the hash check, often from an incomplete copy or a broken download."),
        "fail.damagedNSP.next": ("请重新导出或重新下载这个文件。「仍然构建」会按读到的样子写出损坏的文件，游戏可能因此出错。",
                               "Dump or download the file again. Building anyway writes the damaged files as they are, which may break the game."),
        "fail.damagedNSP.risk": ("会把损坏的文件按读到的样子写出。游戏可能崩溃或显示错误的数据，结果也没有人测试过。这个选择只对这一次构建有效，不会保存。",
                               "This writes the damaged files as they are. The game may crash or show wrong data, and the result is untested. The choice applies to this one build and is not saved."),
        "fail.a32Program.what": ("这个版本是 32 位的，无法在 Apple 芯片上运行。",
