        "fail.keys.what": ("找不到密钥文件，或者无法读取它。", "The keys file was not found or can't be read."),
        "fail.keys.next": ("请重新选择你的 prod.keys。如果它在外接硬盘上，请先连接硬盘，然后再构建。", "Choose your prod.keys again. If it is on an external drive, connect the drive first. Then build again."),
        "fail.keys.button": ("选择密钥文件", "Choose keys file"),
        "fail.severalGames.what": ("这个文件夹里有不止一个游戏。", "The folder holds more than one game."),
        "fail.severalGames.next": ("每次构建只能处理一个文件夹里的一个游戏。请把其他游戏移出这个文件夹，或把这个游戏的文件放进单独的文件夹，然后再构建。", "A build takes one game per folder. Move the other games out of the folder or put this game's files in a folder of their own, then build again."),
        "fail.noTitleID.what": ("文件夹里的安装包都读不出标题 ID：包里没有票据，文件名里也没有 [标题 ID]。", "No package in the folder has a title ID the build can read: none has a ticket inside and none has [title ID] in its file name."),
        "fail.noTitleID.next": ("请把文件改名，加上它的标题 ID，例如 Game Name [0100XXXXXXXXXXXX].nsp，并使用这个安装包自己的 ID，因为本体、更新和 DLC 各有各的 ID。然后再构建。\n也可能是文件夹里没有 .nsp、.xci、.nsz 或 .xcz 文件（分卷或压缩包，例如 .00、.rar，不会被读取），或者文件还在 iCloud 里没有下载。点「显示文件夹」可以查看。", "Rename the file to include its title ID, like Game Name [0100XXXXXXXXXXXX].nsp, using the ID of that exact package, since the base game, an update and DLC each have their own. Then build again.\nIt can also be that the folder has no .nsp, .xci, .nsz or .xcz files (split or archived parts such as .00 or .rar are not read), or that the files are still in iCloud and not downloaded. Choose Show folder to check."),
        "fail.driveMissing.what": ("存放游戏文件的硬盘没有连接。", "The drive with your game files is not connected."),
        "fail.driveMissing.whatNamed": ("存放游戏文件的硬盘“%@”没有连接。", "The drive “%@” with your game files is not connected."),
        "fail.driveMissing.next": ("请连接硬盘，等它出现在访达里，然后再构建。", "Connect the drive and wait until it shows up in the Finder, then build again."),
        "fail.diskFull.what": ("构建时硬盘的可用空间用完了。", "The drive ran out of free space for the build."),
        "fail.diskFull.whatNeeds": ("可用空间不足，构建在这块硬盘上至少需要 %@ GB。", "There is not enough free space. The build needs at least %@ GB on the drive."),
        "fail.diskFull.next": ("请释放存放构建文件夹的硬盘空间，也就是游戏文件旁边以 _build 结尾的那个文件夹。游戏菜单里的「释放空间」会清除已完成的构建不再需要的内容。然后再构建。", "Free up space on the drive that holds the build folder, the one ending in _build beside your game files. Free space in a game's menu removes what a finished build no longer needs. Then build again."),
        "fail.cloudFolder.what": ("构建文件夹在 iCloud 云盘或其他云端文件夹里。", "The build folder is in iCloud Drive or another cloud folder."),
        "fail.cloudFolder.next": ("云端文件夹会给每个文件加上隐藏的附加数据，构建最后的签名步骤不接受这些数据。请把游戏文件移出 iCloud 云盘，或者在「保存到」里选一个云盘之外的文件夹。然后再构建。", "Cloud folders add hidden data to every file. The signing step at the end of the build refuses it. Move your game files out of iCloud Drive, or choose a folder outside it under Save to. Then build again."),
        "fail.cloudFolder.button": ("选择其他文件夹", "Choose another folder"),
        "fail.teamTaken.what": ("这个游戏的 App ID 已注册给另一个 Apple 团队。", "The game's app ID is registered to another Apple team."),
        "fail.teamTaken.next": ("Xcode 对你的团队拒绝了它，用你的团队专属的 ID 变体也不行。请打开 Xcode > 设置 > 账户，登录以前安装这个游戏的那个 Apple ID，或者在这里选另一个签名团队，然后再构建。", "Xcode refused it for your team, also with your team's own variant of the ID. Open Xcode > Settings > Accounts and sign in with the Apple ID that installed this game before, or choose a different signing team here. Then build again."),
        "fail.noSigningAccount.what": ("Xcode 里没有所选团队的签名账户。", "Xcode has no signing account for the chosen team."),
        "fail.noSigningAccount.next": ("请打开 Xcode > 设置 > 账户，登录你的 Apple ID，确认团队已列出，然后再构建。免费的 Apple ID 就够用，证书由 Xcode 自己创建。", "Open Xcode > Settings > Accounts, sign in with your Apple ID and make sure the team is listed, then build again. A free Apple ID is enough and Xcode creates the certificate itself."),
        "fail.deviceTransfer.what": ("把游戏发送到设备失败。", "Sending the game to the device failed."),
        "fail.deviceTransfer.next": ("请解锁 iPhone 或 iPad，如果出现提示就点「信任」，检查数据线并确认设备保持连接，然后重试。", "Unlock the iPhone or iPad and tap Trust if it asks, check the cable and that the device stays connected, then try again."),
