        "dep.guide.iossdk": "Drei Wege, es zu bekommen: ① Klicke auf „Installieren“, dann lädt diese App eines (keine Apple-ID, etwa 100 MB). ② Suche auf den <a href=\"https://developer.apple.com/download/all/\">Apple-Entwickler-Downloads</a> nach „iPhoneOS“ (Apple-ID erforderlich), entpacke es, tippe dann auf „Ordner wählen …“ und wähle das darin liegende iPhoneOS*.sdk. ③ Kopiere den gleichnamigen Ordner aus Platforms/iPhoneOS.platform/Developer/SDKs/ in Xcode.app auf einem Mac mit Xcode. Das SDK von Apple darf diese App nicht mitliefern.",
