        "dep.guide.iossdk": "Trois façons de l’obtenir\u{a0}: ① appuyez sur Installer et cette app en télécharge un (sans identifiant Apple, environ 100\u{a0}Mo)\u{a0}; ② cherchez «\u{a0}iPhoneOS\u{a0}» dans les <a href=\"https://developer.apple.com/download/all/\">téléchargements développeur Apple</a> (identifiant Apple requis), décompressez, puis appuyez sur Choisir un dossier… et pointez vers le iPhoneOS*.sdk qu’il contient\u{a0}; ③ copiez le dossier du même nom depuis Platforms/iPhoneOS.platform/Developer/SDKs/ de Xcode.app sur un Mac équipé d’Xcode. Le SDK d’Apple ne peut pas être distribué par cette app.",
        "dep.guide.metal": "Le compilateur de shaders Metal est distribué séparément par Apple\u{a0}: téléchargez «\u{a0}Metal Developer Tools for Windows\u{a0}» depuis les <a href=\"https://developer.apple.com/download/all/\">téléchargements développeur Apple</a> (identifiant Apple requis), décompressez, puis appuyez sur Choisir un dossier… et pointez vers le dossier décompressé (contenant metal.exe ou ios/). Une copie installée est trouvée automatiquement aux emplacements habituels.",
